import Foundation

/// A subtitle track a trailer's page offers.
nonisolated struct TrailerCaptionTrack: Equatable {
	// MARK: - Properties
	/// The language tag the track is written in.
	let languageCode: String

	/// The language's name in that language.
	let title: String

	/// A Boolean value indicating whether the track was generated by speech recognition.
	let isAutoGenerated: Bool

	/// The address the track's text is fetched from.
	let address: String

	// MARK: - Functions
	/// Rewrites a WebVTT document as one plain cue per spoken line.
	///
	/// - Parameter document: The document as the page serves it.
	///
	/// - Returns: The rewritten document.
	static func webVTT(cleaning document: String) -> String {
		let normalized = document.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n")
		var cues: [(start: String, end: String, text: String)] = []

		for block in normalized.components(separatedBy: "\n\n") {
			let lines = block.components(separatedBy: "\n")
			guard let timingIndex = lines.firstIndex(where: { $0.contains("-->") }) else { continue }

			let parts = lines[timingIndex].components(separatedBy: "-->")
			guard parts.count == 2, let start = parts[0].split(separator: " ").first, let end = parts[1].split(separator: " ").first else { continue }

			var textLines = lines[(timingIndex + 1)...].map(Self.strippingTags(from:)).filter { !$0.isEmpty }
			let previousText = cues.last?.text

			if textLines.count > 1, textLines.first == previousText {
				textLines.removeFirst()
			}

			let text = textLines.joined(separator: "\n")
			guard !text.isEmpty else { continue }

			if text == previousText, let startSeconds = Self.seconds(fromTimestamp: String(start)), let endSeconds = Self.seconds(fromTimestamp: String(end)), endSeconds - startSeconds < 0.1 {
				continue
			}

			cues.append((String(start), String(end), text))
		}

		return "WEBVTT\n\n" + cues.map { "\($0.start) --> \($0.end)\n\($0.text)\n" }.joined(separator: "\n")
	}

	/// Returns a WebVTT document with the timestamp map a stream segment carries.
	///
	/// - Parameter document: The plain document.
	///
	/// - Returns: The document for the stream.
	static func streamWebVTT(from document: String) -> String {
		return document.replacingOccurrences(of: "WEBVTT\n\n", with: "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:0,LOCAL:00:00:00.000\n\n")
	}

	/// Returns the second the last cue of a WebVTT document ends at.
	///
	/// - Parameter document: The document to read.
	///
	/// - Returns: The seconds from the start of the track.
	static func duration(ofWebVTT document: String) -> Double {
		let ends = document.components(separatedBy: "\n").compactMap { line -> Double? in
			guard let end = line.components(separatedBy: "-->").dropFirst().first else { return nil }
			return Self.seconds(fromTimestamp: end)
		}

		return ends.max() ?? 0.0
	}

	/// Returns a cue line's text with its tags removed.
	///
	/// - Parameter line: The line as written in the document.
	///
	/// - Returns: The plain text.
	private static func strippingTags(from line: String) -> String {
		var text = ""
		var isInsideTag = false

		for character in line {
			if character == "<" {
				isInsideTag = true
			} else if character == ">", isInsideTag {
				isInsideTag = false
			} else if !isInsideTag {
				text.append(character)
			}
		}

		return text.replacingOccurrences(of: "  ", with: " ").trimmingCharacters(in: .whitespaces)
	}

	/// Returns the seconds a WebVTT timestamp stands for.
	///
	/// - Parameter timestamp: The timestamp with any cue settings after it.
	///
	/// - Returns: The seconds from the start of the track.
	private static func seconds(fromTimestamp timestamp: String) -> Double? {
		guard let clock = timestamp.split(separator: " ").first else { return nil }

		var seconds = 0.0

		for part in clock.split(separator: ":") {
			guard let value = Double(part) else { return nil }
			seconds = seconds * 60.0 + value
		}

		return seconds
	}
}
